def countAnagramWindowPairs(s, k):
    n = len(s)
    cnt = [0] * 26
    groups = {}
    ans = 0
    for i in range(n):
        cnt[ord(s[i]) - 97] += 1
        if i >= k:
            cnt[ord(s[i - k]) - 97] -= 1
        if i >= k - 1:
            key = tuple(cnt)
            g = groups.get(key, 0)
            ans += g
            groups[key] = g + 1
    return ans
